#include "ui/PresetBrowser.h"

namespace noxis::ui {
PresetBrowser::PresetBrowser():entries(factoryPresets()),favoritesFile(juce::File::getSpecialLocation(juce::File::userApplicationDataDirectory).getChildFile("NOXIS").getChildFile("favorites.txt")){
    for(auto* c:std::initializer_list<juce::Component*>{&list,&search,&category,&favoriteOnly,&favorite,&preview,&apply,&description})addAndMakeVisible(c);
    search.setTextToShowWhenEmpty(utf8("Поиск по имени, тегам и описанию"),muted());search.onTextChange=[this]{refresh();};
    category.addItem(utf8("Все категории"),1);category.addItemList({"INIT","BASS","LEAD","PAD","PLUCK","PHONK","FX","USER"},2);category.setSelectedId(1,juce::dontSendNotification);category.onChange=[this]{refresh();};
    favoriteOnly.setClickingTogglesState(true);favoriteOnly.onClick=[this]{refresh();};
    favorite.onClick=[this]{const auto& name=entries[static_cast<std::size_t>(selected)].name;if(favorites.contains(name))favorites.erase(name);else favorites.insert(name);saveFavorites();showDescription();refresh();};
    apply.onClick=[this]{if(onLoad)onLoad(selected);};preview.onClick=[this]{if(onPreview)onPreview(selected);};
    list.setRowHeight(48);list.setColour(juce::ListBox::backgroundColourId,background());list.setOutlineThickness(0);
    description.setJustificationType(juce::Justification::topLeft);description.setFont(juce::FontOptions(14));description.setColour(juce::Label::textColourId,muted());
    juce::StringArray saved;saved.addLines(favoritesFile.loadFileAsString());for(const auto& item:saved)if(item.isNotEmpty())favorites.insert(item.toStdString());
    const auto folder=juce::File::getSpecialLocation(juce::File::userDocumentsDirectory).getChildFile("NOXIS Presets");auto files=folder.findChildFiles(juce::File::findFiles,false,"*.noxis");
    for(int i=0;i<std::min(256,files.size());++i){Preset p;std::string error;if(loadPreset(std::filesystem::path(files[i].getFullPathName().toWideCharPointer()),p,error)){users.insert(static_cast<int>(entries.size()));entries.push_back(std::move(p));}}
    refresh();showDescription();
}
void PresetBrowser::refresh(){visible.clear();const auto query=search.getText().trim();const int cat=category.getSelectedId();for(std::size_t i=0;i<entries.size();++i){const auto& p=entries[i];if(favoriteOnly.getToggleState()&&!favorites.contains(p.name))continue;if(cat==9&&!users.contains(static_cast<int>(i)))continue;if(cat>1&&cat!=9&&juce::String(p.category)!=category.getText())continue;const auto content=juce::String::fromUTF8((p.name+" "+p.tags+" "+p.description).c_str());if(query.isNotEmpty()&&!content.containsIgnoreCase(query))continue;visible.push_back(static_cast<int>(i));}list.updateContent();selecting=true;auto it=std::find(visible.begin(),visible.end(),selected);if(it!=visible.end())list.selectRow(static_cast<int>(it-visible.begin()));else list.deselectAllRows();selecting=false;repaint();}
void PresetBrowser::select(int value){selected=juce::jlimit(0,static_cast<int>(entries.size())-1,value);refresh();showDescription();}
int PresetBrowser::addUserPreset(const Preset& p){for(std::size_t i=factoryPresets().size();i<entries.size();++i)if(entries[i].name==p.name){entries[i]=p;users.insert(static_cast<int>(i));select(static_cast<int>(i));return static_cast<int>(i);}const int n=static_cast<int>(entries.size());entries.push_back(p);users.insert(n);select(n);return n;}
void PresetBrowser::saveFavorites(){favoritesFile.getParentDirectory().createDirectory();juce::String text;for(const auto& name:favorites)text+=juce::String::fromUTF8(name.c_str())+"\n";favoritesFile.replaceWithText(text);}
void PresetBrowser::showDescription(){if(entries.empty())return;const auto& p=entries[static_cast<std::size_t>(selected)];description.setText(juce::String::fromUTF8((p.name+"\n\n"+p.category+"\n\n"+p.description+"\n\n"+p.character+"\n\n"+p.tags).c_str())+utf8("\n\nРекомендуемые MIDI-ноты: ")+juce::String(p.lowNote)+utf8("–")+juce::String(p.highNote),juce::dontSendNotification);favorite.setButtonText(favorites.contains(p.name)?utf8("Убрать из избранного"):utf8("В избранное"));repaint();}
void PresetBrowser::selectedRowsChanged(int row){if(selecting||row<0||row>=static_cast<int>(visible.size()))return;selected=visible[static_cast<std::size_t>(row)];showDescription();}
void PresetBrowser::listBoxItemDoubleClicked(int row,const juce::MouseEvent&){if(row>=0&&row<static_cast<int>(visible.size())&&onLoad)onLoad(visible[static_cast<std::size_t>(row)]);}
void PresetBrowser::paintListBoxItem(int row,juce::Graphics& g,int width,int height,bool chosen){if(row<0||row>=static_cast<int>(visible.size()))return;const auto& p=entries[static_cast<std::size_t>(visible[static_cast<std::size_t>(row)])];g.setColour(chosen?purple().withAlpha(.13f):(row%2?panelColour():background()));g.fillRoundedRectangle(0,1,static_cast<float>(width),static_cast<float>(height-2),5);g.setColour(chosen?purple():text());g.setFont(juce::FontOptions(14,juce::Font::bold));g.drawText(juce::String::fromUTF8(p.name.c_str()),12,4,width-116,21,juce::Justification::left);g.setColour(muted());g.setFont(juce::FontOptions(10));g.drawText(juce::String::fromUTF8(p.tags.c_str()),12,27,width-24,15,juce::Justification::left);g.setColour(pink());g.drawText(juce::String(p.category)+(favorites.contains(p.name)?" *":""),width-106,5,94,20,juce::Justification::right);}
void PresetBrowser::paint(juce::Graphics& g){g.setColour(panelColour());g.fillRoundedRectangle(getLocalBounds().toFloat(),10);if(visible.empty()){g.setColour(muted());g.drawText(utf8("Нет подходящих пресетов"),list.getBounds(),juce::Justification::centred);}}
void PresetBrowser::resized(){auto r=getLocalBounds().reduced(14);auto top=r.removeFromTop(32);category.setBounds(top.removeFromLeft(160));top.removeFromLeft(10);favoriteOnly.setBounds(top.removeFromRight(120));top.removeFromRight(10);search.setBounds(top);r.removeFromTop(12);auto detail=r.removeFromRight(std::max(260,r.getWidth()/3));r.removeFromRight(14);list.setBounds(r);auto buttons=detail.removeFromBottom(110);preview.setBounds(buttons.removeFromTop(30));buttons.removeFromTop(7);apply.setBounds(buttons.removeFromTop(30));buttons.removeFromTop(7);favorite.setBounds(buttons.removeFromTop(30));description.setBounds(detail);}
}
